  choices = $EXPL$["Each receipt and issue is recorded in real time, maintaining a continuous balance","Inventory is counted and valued only at year-end during a physical count","Inventory quantities are estimated using published industry benchmark data","Inventory is recorded only when a quarterly physical count is performed"]$EXPL$::jsonb,
