-- Q3501: Data Management and Lifecycle [easy/L1]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["A flat file system that stores data in text files with no defined relationships","A spreadsheet application used primarily for ad hoc financial analysis tasks","A system with structured tables, defined relationships, and SQL query support","A document storage system with no structured query or retrieval capability"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (C): An RDBMS organizes data into structured tables linked through primary and foreign key relationships and uses SQL for data manipulation, per the ANSI/ISO SQL standard. This architecture enforces referential integrity and supports complex queries across related tables.
Wrong (A): Flat file systems store data in unstructured text without defined relationships or referential integrity, failing the controller''s data integrity requirement.
Wrong (B): Spreadsheet applications lack enforced relationships, ACID compliance, and multi-user concurrency controls required for an accounting system.
Wrong (D): A document storage system without query capability cannot support the structured data retrieval and relationship enforcement the controller requires.$EXPL$
