-- Q3509: Data Management and Lifecycle [easy/L1]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["Processes individual transactions in real time for operational OLTP systems","Pulls data from sources, standardizes formats, and loads into the warehouse","Distributes web content to users through a global delivery network","Performs multidimensional analysis of historical datasets using OLAP cubes"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (B): ETL (Extract, Transform, Load) is the standard data integration process for populating a data warehouse, per COBIT 2019 DSS06. Data is extracted from source systems, transformed to reconcile differing formats, and loaded into the target warehouse for analysis.
