UPDATE questions SET
  choices = $EXPL$["A central fact table with metrics surrounded by descriptive dimension tables","A single denormalized table that contains all organizational data together","A fully normalized set of tables structured in third normal form","A collection of unrelated flat files stored in a shared directory"]$EXPL$::jsonb,
