-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["Reformatting is the most secure data destruction method currently available","Reformatting destroys data more thoroughly than physical destruction methods","Financial data on decommissioned drives does not require secure destruction","Reformatting removes only file references, leaving data recoverable by forensic tools"]$EXPL$::jsonb,
