-- Q3523: Data Management and Lifecycle [easy/L1]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["INSERT INTO — adds new records to tables","CREATE TABLE — defines a new table structure","DROP TABLE — permanently removes a table and its data","SELECT ... FROM ... WHERE — retrieves filtered data"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (D): The SELECT statement with FROM and WHERE clauses retrieves specific columns and rows from a database table, per COBIT 2019 DSS06. SELECT specifies columns, FROM identifies the source table, and WHERE filters rows by condition.
